if ($c.Contains($o84)) { $c = $c.Replace($o84, $n84) } else { Write-Host "  mist: $o84" -ForegroundColor Yellow }
$o85 = DecodeHex '646174612d656e2d70683d274174206c656173742036206368617261637465727327'
$n85 = DecodeHex '646174612d656e2d70683d274174206c65617374203620636861726163746572732720646174612d69742d70683d22416c6d656e6f20362063617261747465726922'
if ($c.Contains($o85)) { $c = $c.Replace($o85, $n85) } else { Write-Host "  mist: $o85" -ForegroundColor Yellow }
$o86 = DecodeHex '646174612d656e2d70683d27652e672e204c203132333435363738204127'
$n86 = DecodeHex '646174612d656e2d70683d27652e672e204c20313233343536373820412720646174612d69742d70683d2265732e204c203132333435363738204122'
if ($c.Contains($o86)) { $c = $c.Replace($o86, $n86) } else { Write-Host "  mist: $o86" -ForegroundColor Yellow }
$o87 = DecodeHex '646174612d656e2d6f70743d2743686f6f73652061206369747927'
$n87 = DecodeHex '646174612d656e2d6f70743d2743686f6f7365206120636974792720646174612d69742d6f70743d22536365676c6920756e612063697474c3a022'
if ($c.Contains($o87)) { $c = $c.Replace($o87, $n87) } else { Write-Host "  mist: $o87" -ForegroundColor Yellow }

[System.IO.File]::WriteAllText($target, $c, (New-Object System.Text.UTF8Encoding($false)))

$check = [System.IO.File]::ReadAllText($target, [System.Text.Encoding]::UTF8)
$nDataIt = ([regex]::Matches($check, "data-it(-ph|-opt)?=")).Count
$nDataEn = ([regex]::Matches($check, "data-en=")).Count
Write-Host ""
Write-Host "Controle na wijziging:" -ForegroundColor Cyan
Write-Host "  data-it= attributen gevonden: $nDataIt  (verwacht: 98)"
Write-Host "  data-en= attributen gevonden: $nDataEn  (moet ongewijzigd zijn)"
Write-Host "  langBtn / toggleLang aanwezig: $($check.Contains('toggleLang'))"
Write-Host ""

if ($nDataIt -lt 98) {
    Write-Host "WAARSCHUWING: niet alle Italiaanse teksten zijn toegevoegd. NIET automatisch deployen - controleer eerst." -ForegroundColor Red
    exit 1
}

Write-Host "=== Deployen naar Cloudflare Pages ===" -ForegroundColor Cyan
Set-Location $ProjectPath
$wt = Join-Path $ProjectPath "wrangler.toml"
if (Test-Path $wt) { Rename-Item $wt "$wt.bak" -Force }
try {
    npx wrangler pages deploy public --project-name=savoraapp
} finally {
    if (Test-Path "$wt.bak") { Rename-Item "$wt.bak" $wt -Force }
}
Write-Host "Klaar. Test https://savoraapp.com/partner.html (Ctrl+Shift+R) en klik de taalknop 3x: SQ -> EN -> IT -> SQ." -ForegroundColor Cyan